function logCbtActivity($module, $action, $details = '') {
    if (!isset($_SESSION['activity_logs'])) {
        $_SESSION['activity_logs'] = [];
    }
    $ip = $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1';
    $user = $_SESSION['cbt_user'] ?? 'System';
    if ($user === 'admin') $user = 'Administrator CBT (admin)';
    elseif ($user === 'guru') $user = 'Guru Pengawas (' . ($_SESSION['teachers_list'][0]['name'] ?? 'guru') . ')';
    elseif ($user === 'siswa') $user = 'Siswa (' . ($_SESSION['active_student']['name'] ?? 'siswa') . ')';

    array_unshift($_SESSION['activity_logs'], [
        'id' => (string)(count($_SESSION['activity_logs']) + 1),
        'timestamp' => date('d/m/Y H:i:s'),
        'user' => $user,
        'module' => strtoupper($module),
        'action' => strtoupper($action),
        'ip' => $ip,
        'details' => $details,
    ]);
    if (count($_SESSION['activity_logs']) > 80) {
        array_pop($_SESSION['activity_logs']);
    }
}

// Catat Presensi & Sesi Monitoring Siswa Otomatis Berdasarkan Event Login (Web & Mobile Android)
function recordStudentLogin($student, $clientIp = null, $userAgent = null, $deviceOverride = null) {
    if (!$clientIp) $clientIp = $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1';
    if (!$userAgent) $userAgent = $_SERVER['HTTP_USER_AGENT'] ?? '';
    
    // Deteksi jenis perangkat
    if ($deviceOverride) {
        $device = $deviceOverride;
    } elseif (str_contains($userAgent, 'Android') || str_contains($userAgent, 'Mobile') || str_contains($userAgent, 'Dart')) {
        $device = 'Android Kiosk / HP';
    } elseif (str_contains($userAgent, 'iPad') || str_contains($userAgent, 'Tablet')) {
        $device = 'Tablet Kiosk';
    } else {
        $device = 'PC Desktop / Web';
    }

    $nis = $student['nis'];
    $currentTime = date('H:i:s');
    $currentDate = date('d/m/Y');

    // 1. Rekam Absensi Siswa
    if (!isset($_SESSION['student_attendance'])) {
        $_SESSION['student_attendance'] = [];
    }
    $_SESSION['student_attendance'][$nis] = [
        'nis' => $nis,
        'name' => $student['name'],
        'class' => $student['class'] ?? '10-TKJ',
        'login_time' => $currentTime,
        'login_date' => $currentDate,
        'ip' => $clientIp,
        'device' => $device,
        'status' => 'HADIR',
        'timestamp' => time(),
    ];

    // 2. Perbarui status siswa di students_list menjadi Online
    if (isset($_SESSION['students_list'])) {
        foreach ($_SESSION['students_list'] as &$st) {
            if ($st['nis'] === $nis) {
                $st['status'] = 'Online';
                break;
            }
        }
        unset($st);
    }

    // 3. Sinkronkan ke monitoring_sessions agar tampil di telemetri live
    if (!isset($_SESSION['monitoring_sessions'])) {
        $_SESSION['monitoring_sessions'] = [];
    }
    $found = false;
    foreach ($_SESSION['monitoring_sessions'] as &$ms) {
        if ($ms['nis'] === $nis) {
            $ms['login_time'] = $currentTime;
            $ms['ip'] = $clientIp;
            $ms['device'] = $device;
            $ms['attendance_status'] = 'HADIR';
            if ($ms['status'] === 'Belum Mulai' || empty($ms['status']) || $ms['status'] === 'Offline') {
                $ms['status'] = 'Mengerjakan';
            }
            $found = true;
            break;
        }
    }
    unset($ms);

    if (!$found) {
        $assignedExamId = 'ex-1';
        $assignedToken = 'TKJ10A';
        $assignedSubject = 'Dasar Teknik Jaringan Komputer (DTKJ)';
        if (isset($_SESSION['exams_list'])) {
            foreach ($_SESSION['exams_list'] as $exTgt) {
                if (($exTgt['class'] ?? '') === ($student['class'] ?? '')) {
                    $assignedExamId = $exTgt['id'];
                    $assignedToken = $exTgt['token'] ?? 'TKJ10A';
                    $assignedSubject = $exTgt['subject'] ?? 'Umum';
                    break;
                }
            }
        }
        $_SESSION['monitoring_sessions'][] = [
            'nis' => $nis,
            'name' => $student['name'],
            'class' => $student['class'] ?? '10-TKJ',
            'token' => $assignedToken,
            'subject' => $assignedSubject,
            'answered' => 0,
            'total' => 5,
            'time_left' => '90:00',
            'status' => 'Mengerjakan',
            'ip' => $clientIp,
            'device' => $device,
            'exam_id' => $assignedExamId,
            'violations' => 0,
            'is_locked' => false,
            'login_time' => $currentTime,
            'attendance_status' => 'HADIR',
        ];
    }
}

// Rekap Data Presensi & Absensi Siswa Berdasarkan Event Login (Terfilter per Exam & Kelas)
function getCompleteStudentAttendance($examId = null, $classFilter = null) {
    $students = $_SESSION['students_list'] ?? [];
    $attendanceMap = $_SESSION['student_attendance'] ?? [];
    $sessionsMap = [];
    if (isset($_SESSION['monitoring_sessions'])) {
        foreach ($_SESSION['monitoring_sessions'] as $ms) {
            if (!$examId || ($ms['exam_id'] ?? '') === $examId) {
                $sessionsMap[$ms['nis']] = $ms;
            }
        }
    }

    // Jika target kelas tidak ditentukan secara eksplisit, ambil target kelas dari exam
    if ($examId && empty($classFilter) && isset($_SESSION['exams_list'])) {
        foreach ($_SESSION['exams_list'] as $ex) {
            if ($ex['id'] === $examId && !empty($ex['class'])) {
                $classFilter = $ex['class'];
                break;
            }
        }
    }

    $result = [];
    foreach ($students as $st) {
        $stClass = $st['class'] ?? '10-TKJ';
        // Filter kelas: jangan campur aduk siswa dari kelas lain
        if (!empty($classFilter) && $classFilter !== 'SEMUA' && $stClass !== $classFilter) {
            continue;
        }

        $nis = $st['nis'];
        $att = $attendanceMap[$nis] ?? null;
        $ms = $sessionsMap[$nis] ?? null;

        $hasLoggedIn = !empty($att['login_time']) || (!empty($ms['login_time']) && $ms['login_time'] !== '—') || (!empty($ms['status']) && $ms['status'] !== 'Belum Mulai' && $ms['status'] !== 'Offline');
        $loginTime = $att['login_time'] ?? ($ms['login_time'] ?? ($hasLoggedIn ? '07:15:20' : '—'));
        $loginDate = $att['login_date'] ?? date('d/m/Y');
        $ip = $att['ip'] ?? ($ms['ip'] ?? ($hasLoggedIn ? '192.168.1.101' : '—'));
        $device = $att['device'] ?? ($ms['device'] ?? ($hasLoggedIn ? 'PC Lab (Windows)' : '—'));
        $status = $hasLoggedIn ? 'HADIR' : 'BELUM HADIR';

        $result[] = [
            'nis' => $nis,
            'name' => $st['name'],
            'class' => $stClass,
            'login_time' => $loginTime,
            'login_date' => $loginDate,
            'ip' => $ip,
            'device' => $device,
            'status' => $status,
            'exam_status' => $ms['status'] ?? ($hasLoggedIn ? 'Mengerjakan' : 'Belum Mulai'),
            'score' => $ms['score'] ?? null,
            'violations' => $ms['violations'] ?? 0,
        ];
    }
    return $result;
}

