                        'nis' => $matched['nis'],
                    ],
                    'token' => $token,
                    'token_type' => 'Bearer'
                ]
            ]);
            exit;
        }

        http_response_code(401);
        echo json_encode([
            'success' => false,
            'message' => 'Username / NIS atau kata sandi salah'
        ]);
        exit;
