    if (preg_match('#^/api/v1/attempts/(\d+)/sync$#', $uri) && $method === 'POST') {
        $rawInput = file_get_contents('php://input');
        $input = json_decode($rawInput, true) ?: [];
        $cnt = isset($input['answers']) && is_array($input['answers']) ? count($input['answers']) : 0;
