    $teacher = trim($_POST['teacher'] ?? 'Budi Santoso, S.Pd');
    $format = trim($_POST['format'] ?? 'standard');
    $desc = trim($_POST['description'] ?? '');
    $duration = (int)($_POST['duration'] ?? 120);
    $wPg = (float)($_POST['weight_pg'] ?? 100);
    $wPgMulti = (float)($_POST['weight_pg_multi'] ?? 0);
    $wEssay = (float)($_POST['weight_essay'] ?? 0);
    $wTf = (float)($_POST['weight_tf'] ?? 0);
    $wMatch = (float)($_POST['weight_match'] ?? 0);
    $classes = $_POST['classes'] ?? ['10-TKJ'];
    if (!is_array($classes)) $classes = [$classes];
    $showScore = isset($_POST['show_score']) ? true : false;
    $shuffleQuestions = isset($_POST['shuffle_questions']) ? true : false;
    $shuffleOptions = isset($_POST['shuffle_options']) ? true : false;
    $redirect = trim($_POST['redirect'] ?? '');
    if (empty($redirect)) {
        $referer = $_SERVER['HTTP_REFERER'] ?? '';
        $redirect = str_contains($referer, 'subjects') ? '/admin/subjects' : '/admin/questions';
    }

    $_SESSION['subjects_list'][] = [
        'id' => uniqid('sb_'),
        'code' => $code,
        'name' => $name,
        'teacher' => $teacher,
        'format' => $format,
        'description' => $desc,
        'duration' => $duration,
        'weight_pg' => $wPg,
        'weight_pg_multi' => $wPgMulti,
        'weight_essay' => $wEssay,
        'weight_tf' => $wTf,
        'weight_match' => $wMatch,
        'classes' => $classes,
        'questions_count' => 0,
        'exams_count' => 0,
        'status' => 'active',
        'show_score' => $showScore,
        'shuffle_questions' => $shuffleQuestions,
        'shuffle_options' => $shuffleOptions,
    ];
    $visText = $showScore ? 'Nilai Siswa: Ditampilkan' : 'Nilai Siswa: Dirahasiakan';
    $rndText = ($shuffleQuestions ? 'Acak Soal: Ya' : 'Acak Soal: Tidak') . ', ' . ($shuffleOptions ? 'Acak Opsi: Ya' : 'Acak Opsi: Tidak');
    logCbtActivity('SUBJECT', 'CREATE_SUBJECT', "Menambahkan bank soal: {$name} ({$code}) oleh guru {$teacher} [{$visText}, {$rndText}]");
    $_SESSION['import_success'] = "Mata Pelajaran / Bank Soal \"{$name}\" berhasil disimpan [{$visText}, {$rndText}]!";
    header("Location: {$redirect}");
    exit;
}

// Toggle Cepat Visibilitas Nilai Per Mata Pelajaran
if ($uri === '/admin/subjects/toggle-score') {
    $id = $_GET['id'] ?? '';
    $redirect = $_GET['redirect'] ?? '/admin/questions';
    foreach ($_SESSION['subjects_list'] as &$sb) {
        if ($sb['id'] === $id || $sb['name'] === $id) {
            $sb['show_score'] = empty($sb['show_score']);
            $state = $sb['show_score'] ? 'DITAMPILKAN KE SISWA' : 'DISEMBUNYIKAN';
            logCbtActivity('SUBJECT', 'TOGGLE_SCORE', "Mengubah visibilitas nilai mapel {$sb['name']} menjadi: {$state}");
            $_SESSION['import_success'] = "Visibilitas nilai mapel <strong>{$sb['name']}</strong> diubah menjadi: <strong>{$state}</strong>!";
            break;
        }
    }
    unset($sb);
    header("Location: {$redirect}");
    exit;
}

if ($method === 'POST' && $uri === '/admin/subjects/edit') {
    $id = $_POST['id'] ?? '';
    foreach ($_SESSION['subjects_list'] as &$sb) {
        if ($sb['id'] === $id) {
            $sb['code'] = strtoupper(trim($_POST['code'] ?? $sb['code']));
            $sb['name'] = trim($_POST['name'] ?? $sb['name']);
            if (isset($_POST['teacher'])) {
                $sb['teacher'] = trim($_POST['teacher']);
            }
            if (isset($_POST['format'])) {
                $sb['format'] = trim($_POST['format']);
            }
            if (isset($_POST['description'])) {
                $sb['description'] = trim($_POST['description']);
            }
            if (isset($_POST['duration'])) {
                $sb['duration'] = (int)$_POST['duration'];
            }
            if (isset($_POST['weight_pg'])) $sb['weight_pg'] = (float)$_POST['weight_pg'];
            if (isset($_POST['weight_pg_multi'])) $sb['weight_pg_multi'] = (float)$_POST['weight_pg_multi'];
            if (isset($_POST['weight_essay'])) $sb['weight_essay'] = (float)$_POST['weight_essay'];
            if (isset($_POST['weight_tf'])) $sb['weight_tf'] = (float)$_POST['weight_tf'];
            if (isset($_POST['weight_match'])) $sb['weight_match'] = (float)$_POST['weight_match'];
            if (isset($_POST['classes'])) {
                $sb['classes'] = is_array($_POST['classes']) ? $_POST['classes'] : [$_POST['classes']];
            }
            if (isset($_POST['has_score_toggle'])) {
                $sb['show_score'] = isset($_POST['show_score']);
            }
            logCbtActivity('SUBJECT', 'EDIT_SUBJECT', "Memperbarui bank soal: {$sb['name']}");
            $_SESSION['import_success'] = "Perubahan bank soal \"{$sb['name']}\" berhasil disimpan!";
            break;
        }
    }
    unset($sb);
    $referer = $_SERVER['HTTP_REFERER'] ?? '/admin/questions';
    header("Location: {$referer}");
    exit;
}

if ($method === 'POST' && $uri === '/admin/subjects/set-classes') {
