// 5. HAPUS PERMANEN BANK SOAL DARI ARSIP
if (($method === 'POST' || $method === 'GET') && (strpos($uri, '/admin/subjects/permanent-delete') !== false || strpos($uri, '/admin/subjects/bulk-permanent-delete') !== false)) {
    $rawIds = $_POST['ids'] ?? [];
