                $arc['status'] = 'active';
                $arc['subject_id'] = $targetSubjId;
                $arc['subject_name'] = $targetSubjName;
                unset($arc['archived_at'], $arc['archived_by']);
                $_SESSION['questions_list'][] = $arc;
                $restoredCount++;
            } else {
                $remainingArchived[] = $arc;
            }
        }
        $_SESSION['archived_questions'] = $remainingArchived;
