    $rawIds = $_POST['ids'] ?? [];
    if (is_string($rawIds)) $rawIds = explode(',', $rawIds);
    $ids = array_filter(array_map('trim', (array)$rawIds));
    $newDate = trim($_POST['target_date'] ?? date('d-m-Y'));
