        'server_port' => 8000,
        'token_refresh_minutes' => 15,
        'active_token' => 'TKJ10A',
        'proctor_unlock_pin' => str_pad(random_int(1000, 9999), 4, '0', STR_PAD_LEFT),
        'student_review' => true,
        'auto_token_release' => true,
        'server_network_mode' => 'auto',
        'server_host_ip' => $detectedIp,
        'offline_strict_mode' => true,
    ];

    // 2. Bersihkan seluruh sesi monitoring, absensi, dan token perangkat zombie
    $_SESSION['monitoring_sessions'] = [];
    $_SESSION['student_attendance'] = [];
    foreach (array_keys($_SESSION) as $k) {
        if (str_starts_with($k, 'active_api_student_')) {
            unset($_SESSION[$k]);
        }
    }

    // 3. Kembalikan semua status 45 siswa menjadi Offline
    if (isset($_SESSION['students_list'])) {
        foreach ($_SESSION['students_list'] as &$st) {
            $st['status'] = 'Offline';
        }
        unset($st);
    }

    // 4. Tandai versi seed sinkron
    $_SESSION['data_seed_version'] = 'v5_tkj45_sync';

    logCbtActivity('SERVER', 'RESTART_CONFIG', 'Restart pengaturan server CBT berhasil dijalankan. Semua sesi perangkat di-reset dan data disinkronkan.');
    $_SESSION['import_success'] = "Pengaturan server berhasil di-restart! Semua sesi perangkat lama telah dibersihkan, status 45 siswa di-offline-kan, dan sistem telah disinkronkan 100%.";
    header('Location: /admin/settings');
    exit;
}

// Reset Sesi Perangkat dari Menu Monitoring
if ($uri === '/admin/monitoring/reset-sessions') {
    $_SESSION['monitoring_sessions'] = [];
    $_SESSION['student_attendance'] = [];
    foreach (array_keys($_SESSION) as $k) {
        if (str_starts_with($k, 'active_api_student_')) {
            unset($_SESSION[$k]);
        }
    }
    if (isset($_SESSION['students_list'])) {
        foreach ($_SESSION['students_list'] as &$st) {
            $st['status'] = 'Offline';
        }
        unset($st);
    }
    logCbtActivity('MONITORING', 'RESET_DEVICES', 'Membersihkan seluruh sesi perangkat pengerjaan dan presensi aktif.');
    $_SESSION['import_success'] = "Seluruh sesi perangkat pengerjaan dan presensi berhasil dibersihkan! 0 perangkat aktif tersisa.";
    $refId = $_GET['id'] ?? 'ex-1';
    $refClass = $_GET['class'] ?? 'SEMUA';
    header("Location: /admin/monitoring?action=show&id=" . urlencode($refId) . "&class=" . urlencode($refClass));
    exit;
}

// --- K2. PROCTOR PIN & UNLOCK ACTIONS ---
if ($method === 'POST' && $uri === '/admin/proctor-pin/update') {
    $newPin = strtoupper(trim($_POST['proctor_unlock_pin'] ?? ''));
    if ($newPin !== '') {
        $_SESSION['cbt_settings']['proctor_unlock_pin'] = $newPin;
        logCbtActivity('PROCTOR', 'UPDATE_PIN', 'Memperbarui PIN Otorisasi Pengawas Ujian menjadi: ' . $newPin);
        $_SESSION['import_success'] = "PIN Otorisasi Pengawas berhasil diperbarui menjadi: " . htmlspecialchars($newPin);
    }
    header('Location: /admin/proctor-pin');
    exit;
}

if ($method === 'POST' && $uri === '/admin/proctor-pin/unlock-student') {
    $nis = trim($_POST['nis'] ?? '');
    $studentName = '';
    if ($nis !== '' && isset($_SESSION['monitoring_sessions'])) {
        foreach ($_SESSION['monitoring_sessions'] as &$ms) {
            if ($ms['nis'] === $nis) {
                $ms['violations'] = 0;
                $ms['is_locked'] = false;
                $ms['status'] = 'Mengerjakan';
                $studentName = $ms['name'];
                break;
            }
        }
        unset($ms);
        logCbtActivity('PROCTOR', 'UNLOCK_SESSION', 'Membuka kunci sesi ujian peserta: ' . $studentName . ' (' . $nis . ')');
        $_SESSION['import_success'] = "Sesi ujian " . htmlspecialchars($studentName) . " berhasil dibuka kembali! Hitungan pelanggaran telah direset ke 0/3.";
    }
    header('Location: /admin/proctor-pin');
    exit;
}

if ($method === 'POST' && $uri === '/admin/proctor-pin/unlock-all') {
    $selectedNisRaw = trim($_POST['selected_nis'] ?? '');
    $selectedNisList = $selectedNisRaw !== '' ? array_filter(array_map('trim', explode(',', $selectedNisRaw))) : [];
    $isSelective = !empty($selectedNisList);

    $unlockedCount = 0;
    if (isset($_SESSION['monitoring_sessions'])) {
        foreach ($_SESSION['monitoring_sessions'] as &$ms) {
            $matches = $isSelective ? in_array($ms['nis'], $selectedNisList, true) : true;
            if ($matches && (!empty($ms['is_locked']) || (!empty($ms['violations']) && $ms['violations'] > 0))) {
                $ms['violations'] = 0;
                $ms['is_locked'] = false;
                $ms['status'] = 'Mengerjakan';
                $unlockedCount++;
            }
        }
        unset($ms);
    }
    if ($isSelective) {
        logCbtActivity('PROCTOR', 'UNLOCK_SELECTED', 'Membuka kunci sesi untuk ' . $unlockedCount . ' peserta terpilih');
        $_SESSION['import_success'] = "Berhasil membuka kunci sesi untuk <strong>{$unlockedCount} peserta yang ditandai</strong>!";
    } else {
        logCbtActivity('PROCTOR', 'UNLOCK_ALL', 'Membuka kunci massal untuk semua peserta ujian (' . $unlockedCount . ' peserta)');
        $_SESSION['import_success'] = "Berhasil membuka kunci sesi untuk <strong>{$unlockedCount} peserta</strong> yang terhenti!";
    }
    header('Location: /admin/proctor-pin');
    exit;
}

// --- L. AUTHENTICATION (LOGIN / LOGOUT) ---
if ($uri === '/logout') {
    setcookie('cbt_user', '', time() - 86400 * 30, '/');
    unset($_SESSION['cbt_user']);
    unset($_SESSION['active_teacher']);
    unset($_SESSION['active_student']);
    unset($_SESSION['active_test_student']);
    header('Location: /login?logged_out=1');
    exit;
}

if ($method === 'POST' && ($uri === '/login' || strpos($uri, 'login') !== false)) {
    $username = trim($_POST['username'] ?? '');
    $password = trim($_POST['password'] ?? '');

    // 1. Cek Login Admin (admin / admin123 atau 12345678)
    if ($username === 'admin' && ($password === 'admin123' || $password === '12345678')) {
        setcookie('cbt_user', 'admin', time() + 86400 * 7, '/');
        $_SESSION['cbt_user'] = 'admin';
        unset($_SESSION['active_teacher']);
        unset($_SESSION['active_student']);
        logCbtActivity('AUTH', 'LOGIN_SUCCESS', 'Administrator CBT berhasil login');
        header('Location: /admin/dashboard');
        exit;
    }

    // 2. Cek Login Guru (username akun guru, password akun atau default 12345678)
    $matchedTeacher = null;
    if (isset($_SESSION['teachers_list']) && is_array($_SESSION['teachers_list'])) {
        foreach ($_SESSION['teachers_list'] as $t) {
            $teacherPass = $t['password'] ?? '12345678';
            if (strcasecmp($t['username'], $username) === 0 && ($password === $teacherPass || $password === '12345678')) {
                $matchedTeacher = $t;
                break;
            }
        }
    }

    if ($matchedTeacher || ($username === 'guru' && ($password === 'guru123' || $password === '12345678'))) {
        if (!$matchedTeacher) {
            $matchedTeacher = $_SESSION['teachers_list'][0] ?? ['id' => 't1', 'name' => 'Guru Pengajar', 'username' => 'guru', 'password' => '12345678'];
        }
        setcookie('cbt_user', 'guru', time() + 86400 * 7, '/');
        $_SESSION['cbt_user'] = 'guru';
        $_SESSION['active_teacher'] = $matchedTeacher;
        unset($_SESSION['active_student']);
        logCbtActivity('AUTH', 'LOGIN_SUCCESS', "Guru pengajar {$matchedTeacher['name']} berhasil login");
        header('Location: /admin/questions');
        exit;
    }

    // 3. Cek Login Siswa (NIS dan Password siswa / default 12345678)
    $matchedStudent = null;
    if (isset($_SESSION['students_list']) && is_array($_SESSION['students_list'])) {
        foreach ($_SESSION['students_list'] as $s) {
            $studentPass = $s['password'] ?? '12345678';
            if (($s['nis'] === $username || (isset($s['username']) && $s['username'] === $username)) && ($password === $studentPass || $password === '12345678')) {
                $matchedStudent = $s;
                break;
            }
        }
    }

    if ($matchedStudent) {
        setcookie('cbt_user', 'siswa', time() + 86400 * 7, '/');
        $_SESSION['cbt_user'] = 'siswa';
        $_SESSION['active_student'] = $matchedStudent;
        unset($_SESSION['active_teacher']);
        logCbtActivity('STUDENT', 'LOGIN_SUCCESS', "Siswa {$matchedStudent['name']} (NIS: {$matchedStudent['nis']}) berhasil login (Presensi Masuk Tercatat)");

        // Rekam Absensi Siswa & Sesi Monitoring Otomatis
        $clientIp = $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1';
        $userAgent = $_SERVER['HTTP_USER_AGENT'] ?? '';
        recordStudentLogin($matchedStudent, $clientIp, $userAgent);

        header('Location: /student/dashboard');
        exit;
    }

    $_SESSION['login_error'] = 'Nama pengguna / NIS atau kata sandi salah. Silakan periksa kembali.';
    header('Location: /login');
    exit;
}

// Current user check: Wajib login per perangkat / per browser
$isLoggedOut = isset($_GET['logged_out']);
$currentUser = null;

if (!$isLoggedOut) {
    if (!empty($_SESSION['cbt_user'])) {
        $currentUser = $_SESSION['cbt_user'];
    } elseif (!empty($_COOKIE['cbt_user'])) {
        $currentUser = $_COOKIE['cbt_user'];
        $_SESSION['cbt_user'] = $currentUser;
    } elseif (isset($_GET['standalone']) && $_GET['standalone'] == '1') {
        $currentUser = (strpos($uri, '/student') === 0) ? 'siswa' : 'admin';
        $_SESSION['cbt_user'] = $currentUser;
    }
}

// Redirect ke dashboard masing-masing jika sudah login dan mengakses root atau /login
if ($uri === '/' || $uri === '/login') {
    if ($currentUser && !$isLoggedOut) {
        if ($currentUser === 'siswa') {
            header('Location: /student/dashboard');
            exit;
        } elseif ($currentUser === 'guru') {
            header('Location: /admin/questions');
            exit;
        } else {
            header('Location: /admin/dashboard');
            exit;
        }
    }
    renderLoginPage();
    exit;
}

// WAJIB LOGIN: Siapapun tanpa akun terautentikasi wajib diarahkan ke /login
if (!$currentUser) {
    header('Location: /login');
    exit;
}

// 1. Role Siswa: Hanya diarahkan ke portal siswa
if ($currentUser === 'siswa') {
    if (strpos($uri, '/student') === 0) {
        renderStudentPortal();
        exit;
    }
    header('Location: /student/dashboard');
    exit;
}

// 2. Role Guru: Diarahkan ke portal guru
if ($currentUser === 'guru') {
    if (strpos($uri, '/admin') === 0 || strpos($uri, '/guru') === 0) {
        renderAppPage($uri);
        exit;
    }
    header('Location: /admin/questions');
    exit;
}

// 3. Role Admin: Diarahkan ke portal admin
if (strpos($uri, '/admin') === 0) {
    renderAppPage($uri);
    exit;
}

header('Location: /admin/dashboard');
exit;

